// Regenerates assets/fixtures.js (a script-tag friendly copy) from assets/fixtures.json.
// assets/fixtures.json is a verbatim copy of spec/fixtures.json in dhairyab0069/Atlas-Mobile.
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, '..', 'assets');
const json = JSON.parse(fs.readFileSync(path.join(dir, 'fixtures.json'), 'utf8'));
fs.writeFileSync(path.join(dir, 'fixtures.js'),
  '/* generated by tests/gen.js from fixtures.json (a copy of Atlas-Mobile spec/fixtures.json) */\nwindow.ATLAS_FIXTURES = ' +
  JSON.stringify(json, null, 1) + ';\n');
